use crate::repository::{Database,rows,err};
use rusqlite::{Connection,params_from_iter,types::Value as SqlValue};
use serde::Deserialize;
use serde_json::{Value,json};
use std::io::Write;
#[derive(Default,Clone,Deserialize)]#[serde(default,rename_all="camelCase")]
pub struct ReportFilter{pub template_id:Option<i64>,pub doctor_ids:Vec<i64>,pub month:Option<String>,pub title:Option<String>,pub by_decisions:bool,pub decision_id:Option<i64>,pub decision_caption:Option<String>,pub branch_id:Option<i64>}
const FILTER:&str=include_str!("../reports-filter.sql");
fn parameters(from:&str,to:&str,filter:&ReportFilter)->Result<Vec<SqlValue>,String>{
 if filter.branch_id==Some(0)||filter.decision_caption.as_ref().is_some_and(|s|s.len()>500_000){return Err("Некорректный фильтр заключений".into())}
 let first=chrono::NaiveDate::parse_from_str(from,"%Y-%m-%d").map_err(|_|"Проверьте начало периода")?;let last=chrono::NaiveDate::parse_from_str(to,"%Y-%m-%d").map_err(|_|"Проверьте окончание периода")?;
 if from.len()!=10||to.len()!=10||first.format("%Y-%m-%d").to_string()!=from||last.format("%Y-%m-%d").to_string()!=to{return Err("Укажите даты в формате ГГГГ-ММ-ДД".into())}
 if first>last{return Err("Начало периода позже окончания".into())}
 if filter.template_id.is_some_and(|id|id<0)||filter.doctor_ids.len()>200||filter.doctor_ids.iter().any(|id|*id<0)||filter.title.as_ref().is_some_and(|s|s.len()>1000){return Err("Некорректные фильтры отчёта".into())}
 if let Some(month)=&filter.month{if month.len()!=7||chrono::NaiveDate::parse_from_str(&format!("{month}-01"),"%Y-%m-%d").is_err(){return Err("Проверьте месяц отчёта".into())}}
 Ok(vec![from.to_string().into(),(if to=="9999-12-31"{"9999-12-32".to_string()}else{last.succ_opt().ok_or("Конец периода за пределами календаря")?.format("%Y-%m-%d").to_string()}).into(),filter.template_id.map(SqlValue::Integer).unwrap_or(SqlValue::Null),serde_json::to_string(&filter.doctor_ids).map_err(err)?.into(),filter.month.clone().map(SqlValue::Text).unwrap_or(SqlValue::Null),filter.title.clone().map(SqlValue::Text).unwrap_or(SqlValue::Null),filter.decision_id.map(SqlValue::Integer).unwrap_or(SqlValue::Null),filter.decision_caption.clone().map(SqlValue::Text).unwrap_or(SqlValue::Null),filter.branch_id.map(SqlValue::Integer).unwrap_or(SqlValue::Null)])
}

#[cfg(test)]mod tests{
 use super::*;
 fn fixture()->Database{let root=std::env::temp_dir().join(format!("uzi-reports-{}",chrono::Utc::now().timestamp_nanos_opt().unwrap()));std::fs::create_dir_all(&root).unwrap();let db=Database::new(root.join("uzi.db"));let c=Connection::open(&db.path).unwrap();c.execute_batch(include_str!("../schema.sql")).unwrap();c.execute_batch(include_str!("../extended.sql")).unwrap();c.execute_batch("PRAGMA foreign_keys=OFF;PRAGMA user_version=2;INSERT INTO patients(id,name,search_name,gender,hidden) VALUES(1,'=Пациент','пациент','F',0),(2,'Скрытая карточка','скрытая карточка','M',1);INSERT INTO doctors VALUES(1,'Историческая подпись',0),(2,'Второй врач',1);INSERT INTO templates VALUES(1,'Вид 1','universal'),(2,'Вид 2','shit');").unwrap();
  for (id,patient,doctor,kind,date,status,title) in [(1,1,1,1,"2026-11-08","final","Прежнее название"),(2,2,2,2,"2026-11-08 23:59:59","legacy:1","Вид 2"),(3,1,1,2,"2026-11-08","draft","Вид 2"),(4,1,2,1,"2026-11-08","deleted","Прежнее название"),(5,0,1,1,"2026-11-08","final","Без пациента"),(6,1,2,1,"2026-11-08","legacy:2","Прежнее название"),(7,1,1,1,"2026-11-09","final","Прежнее название"),(8,1,2,1,"2026-11-08","final","Прежнее название"),(9,1,1,1,"2026-11-08","final","Новое название")]{c.execute("INSERT INTO studies(id,patient_id,date,template_id,doctor_id,title,conclusion,addition,fields_json,origin,status) VALUES(?,?,?,?,?,?,' =Формула','','{}','native',?)",rusqlite::params![id,patient,date,kind,doctor,title,status]).unwrap();}drop(c);db.save_doctor(Some(1),Some(1),"Текущее имя",false).unwrap();db}
 fn clean(db:Database){std::fs::remove_dir_all(db.path.parent().unwrap()).unwrap()}
 #[test]fn aggregates_and_drilldowns_use_identical_type_doctor_month_and_title_filters(){let db=fixture();let filter=ReportFilter::default();let stats=db.statistics_filtered("2026-11-08","2026-11-08",&filter).unwrap();assert_eq!(stats["summary"]["studies"],4);assert_eq!(stats["summary"]["patients"],2);for key in ["byType","byDoctor","byMonth"]{let sum:i64=stats[key].as_array().unwrap().iter().map(|r|r["count"].as_i64().unwrap()).sum();assert_eq!(sum,4);for row in stats[key].as_array().unwrap(){let mut drill=filter.clone();match key{"byType"=>{drill.template_id=row["id"].as_i64();drill.title=row["name"].as_str().map(str::to_string)},"byDoctor"=>drill.doctor_ids=vec![row["id"].as_i64().unwrap()],_=>drill.month=row["name"].as_str().map(str::to_string)}assert_eq!(db.statistics_details("2026-11-08","2026-11-08",&drill,0,50).unwrap()["total"],row["count"]);}}
  let selected=ReportFilter{template_id:Some(1),doctor_ids:vec![1,1],..Default::default()};assert_eq!(db.statistics_filtered("2026-11-08","2026-11-08",&selected).unwrap()["summary"]["studies"],2);let details=db.statistics_details("2026-11-08","2026-11-08",&selected,0,50).unwrap();assert!(details["items"].as_array().unwrap().iter().all(|r|r["doctor"]=="Историческая подпись"));let hidden=db.statistics_details("2026-11-08","2026-11-08",&ReportFilter{doctor_ids:vec![2],..Default::default()},0,50).unwrap();assert!(hidden["items"].as_array().unwrap().iter().any(|r|r["patientHidden"]==1));let options=db.statistics_options().unwrap();assert!(options["doctors"].as_array().unwrap().iter().any(|r|r["id"]==2&&r["hidden"]==1));clean(db)
 }
 #[test]fn detail_pagination_and_csv_preserve_the_same_selection_and_escape_spreadsheet_text(){let db=fixture();let filter=ReportFilter{template_id:Some(1),doctor_ids:vec![1],..Default::default()};let a=db.statistics_details("2026-11-08","2026-11-08",&filter,0,1).unwrap();let b=db.statistics_details("2026-11-08","2026-11-08",&filter,1,1).unwrap();assert_eq!(a["total"],2);assert_ne!(a["items"][0]["id"],b["items"][0]["id"]);let path=db.path.with_file_name("details.csv");db.export_statistics_details(path.to_str().unwrap(),"2026-11-08","2026-11-08",&filter).unwrap();let csv=std::fs::read_to_string(&path).unwrap();assert_eq!(csv.lines().count(),3);assert!(csv.contains("'=Пациент"));assert!(csv.contains("' =Формула"));assert!(csv.contains("Историческая подпись"));assert!(!csv.contains("Скрытая карточка"));assert!(db.export_statistics_details(path.to_str().unwrap(),"2026-11-08","2026-11-08",&filter).is_err());let summary=db.path.with_file_name("summary.csv");db.export_statistics_filtered(summary.to_str().unwrap(),"2026-11-08","2026-11-08",&filter).unwrap();let summary=std::fs::read_to_string(summary).unwrap();assert!(summary.contains("\"Врач\";\"Текущее имя\";2"));clean(db)}
 #[test]fn invalid_filters_are_rejected_and_quotes_remain_literal(){let db=fixture();assert!(db.statistics_filtered("2026-11-09","2026-11-08",&ReportFilter::default()).is_err());assert!(db.statistics_filtered("2026-02-30","2026-11-08",&ReportFilter::default()).is_err());assert!(db.statistics_filtered("2026-1-1","2026-11-08",&ReportFilter::default()).is_err());assert!(db.statistics_filtered("2026-11-08","2026-11-08",&ReportFilter{doctor_ids:vec![-1],..Default::default()}).is_err());assert!(db.statistics_filtered("2026-11-08","2026-11-08",&ReportFilter{month:Some("2026-99".into()),..Default::default()}).is_err());assert_eq!(db.statistics_filtered("2026-11-08","2026-11-08",&ReportFilter{title:Some("' OR 1=1 --".into()),..Default::default()}).unwrap()["summary"]["studies"],0);assert_eq!(db.statistics_filtered("9999-12-31","9999-12-31",&ReportFilter::default()).unwrap()["summary"]["studies"],0);clean(db)}
}
fn detail_sql(c:&Connection)->Result<String,String>{let decision_join=crate::decisions::join(c)?;let signature=if crate::lifecycle::exists(c,"study_signatures")?{"COALESCE((SELECT ss.name FROM study_signatures ss WHERE ss.study_id=s.id AND ss.doctor_id=s.doctor_id),d.name,'Врач не указан')"}else{"COALESCE(d.name,'Врач не указан')"};Ok(format!("SELECT s.id,s.patient_id AS patientId,p.name AS patientName,COALESCE(p.hidden,0) AS patientHidden,s.date,s.title,s.template_id AS templateId,s.doctor_id AS doctorId,{signature} AS doctor,s.status,COALESCE(sd.entry_id,0) AS decisionId,COALESCE(sd.caption,'Без группы') AS decisionCaption,substr(s.conclusion,1,300) AS conclusionPreview FROM studies s LEFT JOIN patients p ON p.id=s.patient_id LEFT JOIN doctors d ON d.id=s.doctor_id {decision_join} {FILTER} ORDER BY s.date DESC,s.id DESC"))}
fn cell(text:&str)->String{let trimmed=text.trim_start();let value=if trimmed.starts_with(['=','+','-','@']){format!("'{text}")}else{text.into()};format!("\"{}\"",value.replace('"',"\"\""))}
fn file(path:&str)->Result<std::fs::File,String>{std::fs::OpenOptions::new().write(true).create_new(true).open(path).map_err(|e|format!("Не удалось создать новый файл (существующий не перезаписывается): {e}"))}
impl Database{
 pub fn statistics_options(&self)->Result<Value,String>{let c=self.open()?;let mut types=rows(&c,"SELECT id,name FROM templates ORDER BY name",[])?;for kind in &mut types{kind["hidden"]=json!(Self::template_hidden(&c,kind["id"].as_i64().unwrap())?)}Ok(json!({"templates":types,"doctors":rows(&c,"SELECT id,name,hidden FROM doctors ORDER BY name,id",[])?}))}
 pub fn statistics_filtered(&self,from:&str,to:&str,filter:&ReportFilter)->Result<Value,String>{let args=parameters(from,to,filter)?;let c=self.open()?;let tx=c.unchecked_transaction().map_err(err)?;let decision_join=crate::decisions::join(&tx)?;
  let mut result=json!({"summary":rows(&tx,&format!("SELECT count(*) AS studies,count(distinct s.patient_id) AS patients FROM studies s {decision_join} {FILTER}"),params_from_iter(args.iter()))?.pop().unwrap(),"byType":rows(&tx,&format!("SELECT s.template_id AS id,s.title AS name,count(*) AS count FROM studies s {decision_join} {FILTER} GROUP BY s.template_id,s.title ORDER BY count DESC,s.template_id,s.title"),params_from_iter(args.iter()))?,"byDoctor":rows(&tx,&format!("SELECT s.doctor_id AS id,COALESCE(d.name,'Не указан') AS name,count(*) AS count FROM studies s LEFT JOIN doctors d ON d.id=s.doctor_id {decision_join} {FILTER} GROUP BY s.doctor_id ORDER BY count DESC,s.doctor_id"),params_from_iter(args.iter()))?,"byMonth":rows(&tx,&format!("SELECT substr(s.date,1,7) AS name,count(*) AS count FROM studies s {decision_join} {FILTER} GROUP BY substr(s.date,1,7) ORDER BY name"),params_from_iter(args.iter()))?});if filter.by_decisions{result["byDecision"]=json!(rows(&tx,&format!("SELECT COALESCE(sd.entry_id,0) AS id,COALESCE(sd.caption,'Без группы') AS name,count(*) AS count FROM studies s {decision_join} {FILTER} GROUP BY COALESCE(sd.entry_id,0),COALESCE(sd.caption,'Без группы') ORDER BY count DESC,name"),params_from_iter(args.iter()))?);}tx.commit().map_err(err)?;Ok(result)
 }
 pub fn statistics_details(&self,from:&str,to:&str,filter:&ReportFilter,page:i64,page_size:i64)->Result<Value,String>{let mut args=parameters(from,to,filter)?;let c=self.open()?;let tx=c.unchecked_transaction().map_err(err)?;let decision_join=crate::decisions::join(&tx)?;let total=rows(&tx,&format!("SELECT count(*) AS count FROM studies s {decision_join} {FILTER}"),params_from_iter(args.iter()))?.pop().unwrap()["count"].clone();args.push(page_size.clamp(1,500).into());args.push((page.clamp(0,100000)*page_size.clamp(1,500)).into());let items=rows(&tx,&format!("{} LIMIT ?10 OFFSET ?11",detail_sql(&tx)?),params_from_iter(args.iter()))?;tx.commit().map_err(err)?;Ok(json!({"total":total,"items":items}))}
 pub fn export_statistics_filtered(&self,path:&str,from:&str,to:&str,filter:&ReportFilter)->Result<(),String>{let stats=self.statistics_filtered(from,to,filter)?;let mut csv=String::from("\u{feff}Раздел;Наименование;Количество\r\n");let sections=if filter.by_decisions{vec![("byDecision","Группа заключения")]}else{vec![("byType","Исследование"),("byDoctor","Врач"),("byMonth","Месяц")]};for(key,label)in sections{for row in stats[key].as_array().unwrap(){csv.push_str(&format!("{};{};{}\r\n",cell(label),cell(row["name"].as_str().unwrap_or("")),row["count"]))}}let mut file=file(path)?;file.write_all(csv.as_bytes()).map_err(err)?;file.sync_all().map_err(err)}
 pub fn export_statistics_details(&self,path:&str,from:&str,to:&str,filter:&ReportFilter)->Result<(),String>{let args=parameters(from,to,filter)?;let c=self.open()?;let tx=c.unchecked_transaction().map_err(err)?;let mut file=file(path)?;file.write_all(if filter.by_decisions{"\u{feff}Номер;Дата;Пациент;Карточка;Исследование;Врач в протоколе;Заключение (фрагмент);Группа заключения\r\n".as_bytes()}else{"\u{feff}Номер;Дата;Пациент;Карточка;Исследование;Врач в протоколе;Заключение (фрагмент)\r\n".as_bytes()}).map_err(err)?;
  let sql=detail_sql(&tx)?;let mut offset=0;loop{let mut page_args=args.clone();page_args.push(500.into());page_args.push(offset.into());let records=rows(&tx,&format!("{sql} LIMIT ?10 OFFSET ?11"),params_from_iter(page_args.iter()))?;for row in &records{let mut values=vec![row["id"].to_string(),row["date"].as_str().unwrap_or("").into(),row["patientName"].as_str().unwrap_or("Без карточки пациента").into(),if row["patientHidden"]==1{"Скрыта".into()}else{"Доступна".into()},row["title"].as_str().unwrap_or("").into(),row["doctor"].as_str().unwrap_or("").into(),row["conclusionPreview"].as_str().unwrap_or("").into()];if filter.by_decisions{values.push(row["decisionCaption"].as_str().unwrap_or("Без группы").into())}file.write_all((values.iter().map(|s|cell(s)).collect::<Vec<_>>().join(";")+"\r\n").as_bytes()).map_err(err)?;}if records.len()<500{break}offset+=500;}file.sync_all().map_err(err)?;tx.commit().map_err(err)
 }
}
